import { HierarchyRectangularNode } from '@visx/hierarchy/lib/types';
import { useCallback } from 'react';

import type { MouseCoordinate } from '../../core/types/overlays.js';
import { useSetState } from '../store/selectors.js';
import { InternalTreeMapLeafNode } from '../types/internal.js';

export const useTooltip = () => {
  const setState = useSetState();

  const setTooltipContent = useCallback(
    (tooltipContent: HierarchyRectangularNode<InternalTreeMapLeafNode>) => {
      setState((prev) => ({
        ...prev,
        tooltip: {
          ...prev.tooltip,
          content: tooltipContent,
        },
      }));
    },
    [setState],
  );

  const setTooltipVisible = useCallback(
    (isVisible: boolean) => {
      setState((prev) => ({
        ...prev,
        tooltip: {
          ...prev.tooltip,
          visible: isVisible,
        },
      }));
    },
    [setState],
  );

  const setTooltipPinned = useCallback(
    (isPinned: boolean) => {
      setState((prev) => ({
        ...prev,
        tooltip: {
          ...prev.tooltip,
          pinned: isPinned,
        },
      }));
    },
    [setState],
  );

  const setTooltipPosition = useCallback(
    (position: MouseCoordinate) => {
      setState((prev) => {
        return {
          ...prev,
          tooltip: {
            ...prev.tooltip,
            position,
          },
        };
      });
    },
    [setState],
  );

  return {
    setTooltipContent,
    setTooltipPinned,
    setTooltipVisible,
    setTooltipPosition,
  };
};
